export const ROUTE=GUIDES.flat().map(p=>[p.x,p.y,p.z]);
export function guideTarget(i,p){const a=GUIDES[i]||[];let k=0,best=Infinity;a.forEach((v,j)=>{const d=Math.hypot(p.x-v.x,p.z-v.z);if(d<best){best=d;k=j;}});return a[Math.min(k+1,a.length-1)];}
